head.b:skin:
:root{--red:#c9a45b;--red2:#a9823d;--text:#15130f;--muted:#756f63;--line:#e9e2d5;--bg:#f8f6f1;--card:#fff;--green:#1f7a4d;--aprinna-black:#050505;--aprinna-gold:#d8ba78;--aprinna-gold-dark:#a9823d;--aprinna-cream:#fbf7ec}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:var(--text);font-family:Inter,Arial,sans-serif;font-size:14px}a{color:inherit;text-decoration:none}.site-shell{max-width:1220px;margin:auto;padding:0 18px}.top-strip{background:#f7f7f7;border-bottom:1px solid #ececec;color:#666;font-size:12px}.top-strip .site-shell{min-height:36px;display:flex;align-items:center;justify-content:space-between;gap:15px}.header-main{background:#fff}.header-main .site-shell{height:76px;display:flex;align-items:center;gap:34px}.brand{font-size:29px;font-weight:900;letter-spacing:-1.6px}.brand span{color:var(--red)}.searchbar{height:44px;display:flex;flex:1;max-width:650px;border:2px solid var(--red);border-radius:7px;overflow:hidden}.searchbar input{min-width:0;flex:1;border:0;outline:0;padding:0 16px;font:inherit}.searchbar button{width:54px;border:0;background:var(--red);color:#fff;font-size:18px;cursor:pointer}.header-actions{margin-left:auto;display:flex;gap:18px;font-size:21px}.menu-toggle{display:none;border:0;background:none;font-size:21px}.mobile-search{display:none}.nav-wrap{border-top:1px solid #f1f1f1;border-bottom:1px solid #e9e9e9}.nav{height:47px;display:flex;align-items:center;gap:34px;font-weight:600}.nav a:hover,.nav .deal{color:var(--red)}.shop-layout{max-width:1220px;margin:28px auto 50px;padding:0 18px;display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:28px}.section-head{display:flex;align-items:flex-end;justify-content:space-between;margin:0 0 18px}.section-head h1{margin:0 0 5px;font-size:24px}.section-head p{margin:0;color:#777}.grid-posts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.index-post{min-width:0}.index-post-inside-wrap{height:100%;border:1px solid #e8e8e8;border-radius:10px;background:#fff;overflow:hidden;display:flex;flex-direction:column;transition:.2s}.index-post-inside-wrap:hover{box-shadow:0 7px 22px rgba(0,0,0,.08);transform:translateY(-2px)}.post-image-wrap{position:relative;background:#fafafa;aspect-ratio:1/1;overflow:hidden}.post-image-link{display:block;width:100%;height:100%}.post-thumb{width:100%;height:100%;object-fit:contain;display:block}.product-badge{position:absolute;z-index:2;left:10px;top:10px;background:var(--red);color:#fff;border-radius:4px;padding:6px 8px;font-size:11px;font-weight:800}.wishlist-dot{position:absolute;right:10px;top:10px;z-index:2;width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:#fff;box-shadow:0 2px 8px #ddd;color:#777}.post-info{padding:14px 14px 10px;flex:1}.product-meta{display:flex;justify-content:space-between;gap:8px;color:#999;font-size:11px;margin-bottom:8px}.product-meta .store{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.post-title{margin:0;font-size:14px;line-height:1.45;font-weight:600}.index-post .post-title{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:41px}.rating{display:flex;gap:5px;align-items:center;margin-top:8px;font-size:11px;color:#888}.stars{color:#ff9f00;letter-spacing:1px}.price-row{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:11px}.price-main{font-size:20px;font-weight:800;color:var(--red)}.old-price{font-size:12px;color:#aaa;text-decoration:line-through}.index-post-footer{padding:0 14px 14px;display:flex;gap:8px}.button{height:39px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;font-weight:700}.buy{flex:1;background:var(--red);color:#fff}.quick-view{width:40px;border:1px solid #ddd;border-radius:6px;display:grid;place-items:center}.sidebar .widget,.trust-card{border:1px solid #e8e8e8;border-radius:9px;background:#fff;margin-bottom:18px;padding:17px}.sidebar h3,.widget-title h3{font-size:15px;margin:0 0 13px}.trust-card h3 i{color:var(--green)}.trust-card p{color:#777;line-height:1.6;margin:0}.list-label ul{list-style:none;margin:0;padding:0}.list-label li{border-top:1px solid #f0f0f0}.list-label li:first-child{border-top:0}.list-label a{display:block;padding:9px 0;color:#555}.footer{background:#171717;color:#bbb}.footer-main{padding-top:38px;padding-bottom:32px;display:grid;grid-template-columns:2fr 1fr 1fr;gap:45px}.footer h3{color:#fff;margin:0 0 12px}.footer p{line-height:1.7}.footer-menu{display:flex;flex-direction:column;gap:9px}.copyright{border-top:1px solid #2d2d2d;min-height:56px;display:flex;align-items:center;justify-content:space-between;font-size:12px}.back-top{position:fixed;right:20px;bottom:20px;width:38px;height:38px;border-radius:6px;background:#222;color:#fff;display:none;place-items:center;cursor:pointer}.back-top.show{display:grid}
/* product page */#breadcrumb{font-size:12px;color:#888;margin-bottom:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#breadcrumb .delimiter{display:inline-block;width:7px;height:7px;margin:0 11px 1px 9px;border-top:1px solid #b8c0cc;border-right:1px solid #b8c0cc;transform:rotate(45deg);vertical-align:middle}.product-detail{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:34px}.image-holder{border:1px solid #eee;border-radius:10px;aspect-ratio:1/1;display:grid;place-items:center;overflow:hidden}.image-holder img{width:100%;height:100%;object-fit:contain}.thumb-list{display:flex;gap:9px;margin-top:10px;overflow:auto}.image-list{width:68px;height:68px;border:1px solid #ddd;border-radius:6px;flex:0 0 auto;overflow:hidden}.image-list.active{border:2px solid var(--red)}.image-list img{width:100%;height:100%;object-fit:cover}.product-kicker{font-size:12px;color:#888;margin-bottom:10px}.product-summary .post-title{font-size:24px;line-height:1.4;font-weight:700}.product-price-box{background:#fff6f6;border-radius:8px;padding:15px;margin:18px 0}.product-price-box .price-main{font-size:30px}.discount{background:var(--red);color:#fff;font-size:11px;font-weight:800;border-radius:4px;padding:5px 7px}.availability{margin-top:8px;color:var(--green);font-size:12px}.buy-panel{border:1px solid #eee;border-radius:9px;padding:15px}.buy-panel-label{font-size:12px;color:#777;margin-bottom:11px}.buy-actions{display:flex;gap:9px}.btn-outline{border:1px solid #ddd;flex:.65}.btn-primary{background:var(--red);color:#fff;flex:1}.benefits{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:14px 0}.benefit{border:1px solid #eee;border-radius:7px;padding:10px;text-align:center}.benefit i{display:block;color:var(--red);font-size:18px;margin-bottom:6px}.benefit strong,.benefit span{display:block;font-size:10px}.benefit span{color:#999;margin-top:3px}.product-specs{border-top:1px solid #eee}.rowline{display:flex;justify-content:space-between;gap:20px;padding:10px 0;border-bottom:1px solid #eee;font-size:12px}.rowline .label{color:#888}.description-box{margin-top:28px;border:1px solid #eee;border-radius:9px;padding:22px}.description-box h2{margin:0 0 12px;font-size:19px}.description-box p{line-height:1.8;color:#666}.native-post-wrap{display:block}.native-post-title{font-size:26px;line-height:1.35;margin:0 0 18px}.native-post-body{line-height:1.75;overflow-wrap:anywhere}.native-post-body img{max-width:100%;height:auto}.evx-enhanced-product{display:none}
body.evx-item-view{background:#f5f6f8}body.evx-item-view .shop-layout{display:block;max-width:1240px;margin:28px auto 34px;padding:0 18px}body.evx-item-view .sidebar{display:none}body.evx-item-view .main-area{background:#fff;border:1px solid #e7e9ed;border-radius:18px;padding:26px 24px 34px;box-shadow:0 10px 28px rgba(15,23,42,.05)}body.evx-item-view #breadcrumb{margin:0 0 22px;color:#64748b;font-size:13px}body.evx-item-view .product-detail{grid-template-columns:minmax(0,.94fr) minmax(0,1.06fr);gap:36px}body.evx-item-view .image-holder{border:1px solid #e5e7eb;border-radius:14px;padding:24px;aspect-ratio:1/1;background:#fff}body.evx-item-view .image-list{width:72px;height:72px;border-radius:10px;padding:5px;background:#fff}body.evx-item-view .image-list.active{border-color:#ffae00}body.evx-item-view .image-list img{object-fit:contain}body.evx-item-view .product-kicker{font-size:13px;color:#64748b;margin:6px 0 12px}body.evx-item-view .product-summary .post-title{font-size:31px;line-height:1.27;color:#0f172a;margin:0 0 18px}body.evx-item-view .product-price-box{background:#fafafa;border-radius:14px;padding:26px 18px;margin:0 0 18px}body.evx-item-view .product-price-box .price-main{font-size:32px;font-weight:800}body.evx-item-view .discount{background:#fff1d6;color:#e86b00;padding:5px 8px;border-radius:6px}body.evx-item-view .availability{color:#079447;font-weight:700;margin-top:14px}body.evx-item-view .buy-panel{border:1px solid #e5e7eb;border-radius:14px;padding:18px}body.evx-item-view .buy-actions .button{height:52px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-weight:800}body.evx-item-view .btn-outline{border:1px solid #111827;color:#111827;background:#fff}body.evx-item-view .btn-primary{background:#ffae00;color:#111827}body.evx-item-view .benefit{border:1px solid #e5e7eb;border-radius:12px;padding:16px 8px}body.evx-item-view .benefit i{color:#f59e0b}body.evx-item-view .product-specs{border:1px solid #e5e7eb;border-radius:13px;overflow:hidden}body.evx-item-view .rowline{padding:13px 16px;border-bottom:1px solid #e5e7eb}
body.evx-item-view .item-rating{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
body.evx-item-view .item-rating .item-stars{color:#ffb000;letter-spacing:1px;font-size:18px;line-height:1;white-space:nowrap}
body.evx-item-view .item-rating strong{color:#111827;font-size:13px}
body.evx-item-view .item-rating .item-sold{color:#667085;font-size:12px}body.evx-item-view .description-box{border:0;border-top:1px solid #e5e7eb;border-radius:0;padding:24px 0 0;margin-top:28px}@media(max-width:980px){.grid-posts{grid-template-columns:repeat(2,1fr)}.shop-layout{grid-template-columns:1fr}.sidebar{display:none}.product-detail{grid-template-columns:1fr 1fr}.header-main .site-shell{gap:18px}}
@media(max-width:680px){.top-strip .site-shell>div:last-child{display:none}.header-main .site-shell{height:62px}.header-main .searchbar{display:none}.mobile-search{display:block;padding:9px 0;border-top:1px solid #eee}.mobile-search .searchbar{max-width:none}.menu-toggle{display:block}.nav-wrap{display:none}.nav-wrap.open{display:block}.nav{height:auto;flex-direction:column;align-items:flex-start;padding-top:12px;padding-bottom:12px;gap:0}.nav a{width:100%;padding:10px 0}.shop-layout{margin-top:20px;padding:0 12px}.grid-posts{gap:10px}.post-info{padding:10px}.index-post-footer{padding:0 10px 10px}.product-meta .store{display:none}.price-main{font-size:17px}.old-price{display:none}.product-detail{grid-template-columns:1fr}.product-summary .post-title{font-size:20px}.footer-main{grid-template-columns:1fr;gap:20px}.copyright{flex-direction:column;justify-content:center;gap:5px}.benefits{grid-template-columns:1fr 1fr 1fr}}
#evx-feed-app{min-height:220px}.evx-loading{padding:50px 10px;color:#888;text-align:center}
.evx-error{padding:25px;border:1px solid #ffd0d0;background:#fff8f8;border-radius:8px;color:#a33}
.feed-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.feed-card{border:1px solid #e8e8e8;border-radius:10px;overflow:hidden;background:#fff;display:flex;flex-direction:column}
.feed-card-image{aspect-ratio:1/1;background:#fafafa;display:block;overflow:hidden}
.feed-card-image img{width:100%;height:100%;object-fit:contain;display:block}
.feed-card-image{position:relative}
.feed-card-discount{position:absolute;left:10px;top:10px;z-index:3;background:#ff4747;color:#fff;border-radius:4px;padding:6px 8px;font-size:11px;line-height:1;font-weight:800;letter-spacing:0;box-shadow:0 1px 2px rgba(0,0,0,.08)}
.feed-card-body{padding:14px;display:flex;flex-direction:column;gap:10px;flex:1}
.feed-card-title{font-size:14px;line-height:1.45;font-weight:600;margin:0}
.feed-card-title a{color:inherit}
.feed-card-price-row{display:flex;align-items:baseline;gap:9px;flex-wrap:wrap;margin-top:1px}
.feed-card-price{font-size:20px;font-weight:800;color:var(--red);line-height:1.15}
.feed-card-old-price{font-size:12px;font-weight:400;color:#aaa;text-decoration:line-through;line-height:1.15}
.feed-card-actions{display:flex;gap:8px;margin-top:auto}
.feed-card-actions a{flex:1;height:39px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-weight:700}
.feed-card-actions .view{background:var(--red);color:#fff}
.feed-card-actions .details{flex:0 0 42px;border:1px solid #ddd}
.feed-item-title{font-size:26px;line-height:1.35;margin:0 0 18px}
.feed-item-body{line-height:1.75;overflow-wrap:anywhere}
.feed-item-body img{max-width:100%;height:auto}
@media(max-width:980px){.feed-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:680px){.feed-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.feed-card-body{padding:10px}.feed-card-price{font-size:17px}.feed-card-old-price{font-size:11px}.feed-card-discount{left:7px;top:7px;padding:5px 6px;font-size:10px}}

/* ===== STYLING WIDGET & SIDEBAR ===== */
.sidebar .widget{margin-bottom:18px;border:1px solid #e8e8e8;border-radius:9px;background:#fff;padding:17px;overflow:hidden}
.sidebar .widget h2,.sidebar .widget .widget-title{margin:0 0 13px;font-size:15px;font-weight:700;color:#191919}
.sidebar .widget.PopularPosts,.sidebar .evx-sidebar-popular-widget{padding:0}
.sidebar .widget.PopularPosts h2,.sidebar .widget.PopularPosts .widget-title,.sidebar .evx-sidebar-popular-widget .widget-title{margin:0;padding:14px 17px;border-bottom:1px solid #eceff2;font-size:15px;font-weight:700;color:#191919}
.sidebar .widget.PopularPosts .widget-content,.sidebar .evx-sidebar-popular-widget .widget-content{padding:4px 14px!important}

/* Footer Custom Layout Area */
.footer-widgets{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin-bottom:30px}
.footer-widgets .widget{margin-bottom:0}
.footer-widgets h2{color:#fff;font-size:15px;margin:0 0 12px;font-weight:700}
.footer-widgets .widget-content{color:#bbb;font-size:13px;line-height:1.6}
@media(max-width:768px){.footer-widgets{grid-template-columns:1fr}}

/* ===== EVXRO PRODUCT POST STYLE ===== */
.post-title.entry-title,.native-post-title{display:none!important}
.evx-product-page,.evx-product-page *{box-sizing:border-box}
body.evx-item-view .shop-layout{display:block;max-width:none;margin:28px auto 34px;padding:0}
body.evx-item-view .sidebar{display:none}
body.evx-item-view .main-area{background:transparent;border:0;border-radius:0;padding:0;box-shadow:none}
.evx-product-page{width:min(1320px,calc(100vw - 48px));max-width:1320px;margin:0 0 0 50%;transform:translateX(-50%);background:#fff;border:1px solid #e7eaee;border-radius:16px;padding:26px;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;color:#111827;box-shadow:0 10px 32px rgba(16,24,40,.055);-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;text-rendering:optimizeLegibility}
.evx-breadcrumb{display:flex;align-items:center;flex-wrap:wrap;gap:0;margin:0 0 24px;color:#667085;font-size:13px;font-weight:400;line-height:1.5}
.evx-breadcrumb .crumb{display:inline-flex;align-items:center;min-width:0;color:#667085;text-decoration:none}
.evx-breadcrumb a.crumb:hover{color:#111827}
.evx-breadcrumb .crumb-sep{display:inline-block;width:7px;height:7px;margin:0 11px 1px 9px;border-top:1px solid #b8c0cc;border-right:1px solid #b8c0cc;transform:rotate(45deg);flex:0 0 auto}
.evx-breadcrumb .current{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:640px}
.evx-main{display:grid;grid-template-columns:minmax(0,.96fr) minmax(0,1.04fr);gap:36px;align-items:start}
.evx-image-box{border:1px solid #e5e7eb;border-radius:13px;padding:26px;background:#fff;aspect-ratio:1/1;display:flex;align-items:center;justify-content:center;overflow:hidden}
.evx-main-link{display:block;width:100%;height:100%}
.evx-main-image,.evx-image-box img{width:100%;height:100%;display:block;object-fit:contain}
.evx-no-image{color:#98a2b3}
.evx-thumbs{display:flex;gap:10px;margin-top:12px;overflow-x:auto;padding:0 0 4px;scrollbar-width:thin}
.evx-thumb{display:block;width:70px;height:70px;flex:0 0 70px;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;background:#fff;padding:4px;box-sizing:border-box}
.evx-thumb.active{border:2px solid #f5a000;padding:3px}
.evx-thumb img{display:block;width:100%;height:100%;object-fit:contain}
.evx-kicker{font-size:12px;color:#667085;margin:6px 0 12px;font-weight:400}
.evx-rating{display:flex;align-items:center;gap:9px;margin:-10px 0 20px;font-size:14px;line-height:1;flex-wrap:wrap}
.evx-stars{color:#ffb000;letter-spacing:2px;font-size:20px;white-space:nowrap}
.evx-rating-value{color:#111827;font-weight:800;font-size:16px}
.evx-rating-meta{color:#111827;font-weight:400;font-size:15px}
.evx-rating-divider{color:#111827;font-size:15px;margin:0 1px}
.evx-title{font-size:27px;line-height:1.32;letter-spacing:-.42px;font-weight:700;margin:0 0 22px;color:#1f2937}
.evx-price-box{background:#fafafa;border-radius:13px;padding:29px 19px 20px;margin-bottom:20px}
.evx-price-line{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.evx-price{font-size:34px;line-height:1;font-weight:800;color:#101828;letter-spacing:-.4px}
.evx-discount{padding:6px 8px;border-radius:7px;background:#fff1d8;color:#e36c00;font-size:11px;font-weight:800}
.evx-old-price{color:#98a2b3;text-decoration:line-through;font-size:14px}
.evx-stock{margin-top:22px;color:#079455;font-size:13px;font-weight:700}
.evx-buy-panel{border:1px solid #e5e7eb;border-radius:13px;padding:20px;margin-bottom:18px}
.evx-buy-label{font-size:12px;color:#667085;margin-bottom:10px}
.evx-buy-actions{display:grid;grid-template-columns:.95fr 1.18fr;gap:10px}
.evx-btn{height:52px;border-radius:9px;display:flex;align-items:center;justify-content:center;text-decoration:none!important;font-size:15px;font-weight:800}
.evx-btn-details{border:1px solid #475467;color:#101828;background:#fff}
.evx-btn-buy{background:#ffad08;color:#111827}
.evx-benefits{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:18px}
.evx-benefit{border:1px solid #e5e7eb;border-radius:12px;padding:16px 10px;text-align:center;min-height:100px;display:flex;flex-direction:column;align-items:center;justify-content:center}
.evx-benefit .ico{height:24px;display:flex;align-items:center;justify-content:center;font-size:22px;line-height:1;color:#f5a000;margin-bottom:10px}.evx-benefit .ico .fa{font-size:22px;color:#f5a000}
.evx-benefit strong{font-size:12px;margin-bottom:7px;color:#111827}
.evx-benefit small{font-size:11px;color:#667085}
.evx-specs{border:1px solid #e5e7eb;border-radius:12px;overflow:hidden}
.evx-spec-row{display:grid;grid-template-columns:145px 1fr;gap:8px;padding:13px 16px;border-bottom:1px solid #eaecf0;font-size:13px}
.evx-spec-row:last-child{border-bottom:0}
.evx-spec-label{color:#667085}
.evx-spec-rating{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.evx-spec-stars{color:#ffb000;letter-spacing:1px;font-size:17px;line-height:1;white-space:nowrap}
.evx-spec-rating strong{color:#111827}
.evx-spec-sold{color:#667085}
.evx-about{border-top:1px solid #e5e7eb;margin-top:26px;padding-top:24px}
.evx-about h2{font-size:19px;margin:0 0 17px;color:#101828;font-weight:800}
.evx-description p{margin:0 0 12px;color:#475467;font-size:15px;line-height:1.72}
.evx-description p:last-child{margin-bottom:0}
@media(max-width:900px){.evx-product-page{width:calc(100vw - 24px);padding:16px;border-radius:14px}.evx-main{grid-template-columns:1fr;gap:24px}.evx-title{font-size:23px}.evx-price{font-size:30px}.evx-breadcrumb .current{max-width:100%}}
@media(max-width:560px){.evx-product-page{width:calc(100vw - 12px);padding:12px}.evx-image-box{padding:12px}.evx-buy-actions{grid-template-columns:1fr}.evx-benefits{grid-template-columns:1fr}.evx-spec-row{grid-template-columns:105px 1fr}}

/* ===== REFERENCE TYPOGRAPHY + COLOR SYSTEM ===== */
:root{--red:#c9a45b;--red2:#a9823d;--text:#15130f;--muted:#756f63;--line:#e9e2d5;--bg:#f8f6f1;--card:#ffffff;--green:#1f7a4d;--aprinna-black:#050505;--aprinna-gold:#d8ba78;--aprinna-gold-dark:#a9823d;--aprinna-cream:#fbf7ec;}
html,body{font-family:Inter,"Noto Sans",Arial,sans-serif;color:#191919;background:#fff}
body{font-size:14px;font-weight:400;line-height:1.45;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
a{color:#191919}
.top-strip{background:#f7f7f7;border-bottom-color:#ececec;color:#666;font-size:12px}
.top-strip strong{color:#191919;font-weight:700}
.brand{color:#191919;font-family:Inter,"Noto Sans",Arial,sans-serif;font-size:29px;font-weight:900;letter-spacing:-1.6px}
.brand span{color:#ff4747}
.searchbar{border-color:#ff4747;background:#fff}
.searchbar input{color:#191919;background:#fff;font-family:Inter,"Noto Sans",Arial,sans-serif;font-size:14px;font-weight:400}
.searchbar input::placeholder{color:#8a8a8a;opacity:1}
.searchbar button{background:#ff4747;color:#fff}
.header-actions,.header-actions a,.menu-toggle{color:#191919}
.nav-wrap{border-top-color:#f1f1f1;border-bottom-color:#e9e9e9;background:#fff}
.nav{font-size:14px;font-weight:600;color:#191919}
.nav a{color:#191919}
.nav a:hover,.nav .deal{color:#ff4747}
.section-head h1{color:#191919;font-size:24px;font-weight:700;letter-spacing:-.25px}
.section-head p{color:#777;font-size:13px;font-weight:400}
.feed-card,.index-post-inside-wrap{background:#fff;border-color:#e8e8e8}
.feed-card-title,.post-title{font-family:Inter,"Noto Sans",Arial,sans-serif;color:#191919;font-size:14px;font-weight:600;line-height:1.45;letter-spacing:0}
.feed-card-title a,.post-title a{color:#191919}
.product-meta{color:#999;font-size:11px;font-weight:400}
.rating{color:#888;font-size:11px;font-weight:400}
.stars{color:#ff9f00}
.feed-card-price,.price-main{color:#ff4747;font-size:20px;font-weight:800;letter-spacing:0}
.old-price{color:#aaa;font-size:12px;font-weight:400}
.feed-card-actions .view,.button.buy{background:#ff4747;color:#fff;font-weight:700}
.feed-card-actions .view:hover,.button.buy:hover{background:#e62e2e}
.feed-card-actions .details,.quick-view{background:#fff;border-color:#ddd;color:#191919}
.sidebar .widget,.trust-card{background:#fff;border-color:#e8e8e8;color:#191919}
.sidebar h3,.widget-title h3,.trust-card h3{color:#191919;font-size:15px;font-weight:700}
.trust-card h3 i{color:#00a650}
.trust-card p,.list-label a{color:#777}
.footer{background:#171717;color:#bbb}
.footer h3{color:#fff;font-size:15px;font-weight:700}
.footer p,.footer a,.footer span{color:#bbb}
.footer a:hover{color:#fff}
.copyright{border-top-color:#2d2d2d;color:#aaa}
.back-top{background:#222;color:#fff}
.evx-product-page{font-family:Inter,"Noto Sans",Arial,sans-serif;color:#191919}
.evx-title{font-family:Inter,"Noto Sans",Arial,sans-serif;color:#191919}
.evx-kicker,.evx-breadcrumb,.evx-spec-label,.evx-benefit small,.evx-description p{color:#757575}
.evx-price{color:#191919}
.evx-btn-buy{background:#ffad08;color:#111827}

/* ===== HOME REFERENCE MATCH ===== */
body:not(.evx-item-view){background:#f5f6f8;color:#111820;font-family:Inter,"Noto Sans",Arial,sans-serif}
body:not(.evx-item-view) .site-shell{max-width:1320px;padding-left:20px;padding-right:20px}
body:not(.evx-item-view) .top-strip{background:#11151a;border:0;color:#eef2f5;font-size:11px}
body:not(.evx-item-view) .top-strip .site-shell{min-height:28px}
body:not(.evx-item-view) .top-strip strong{color:#fff}
body:not(.evx-item-view) .header-main{background:#fff}
body:not(.evx-item-view) .header-main .site-shell{height:72px;gap:38px}
body:not(.evx-item-view) .brand{font-size:24px;font-weight:900;letter-spacing:-1.4px;color:#111820}
body:not(.evx-item-view) .brand span{color:#ff4747}
body:not(.evx-item-view) .searchbar{height:46px;max-width:none;border:1px solid #d7dce2;border-radius:24px;background:#f8f9fa;overflow:hidden}
body:not(.evx-item-view) .searchbar input{background:transparent;color:#4b5563;padding-left:18px;font-size:13px}
body:not(.evx-item-view) .searchbar input::placeholder{color:#7b8490}
body:not(.evx-item-view) .searchbar button{width:58px;background:#11151a;color:#fff;font-size:15px}
body:not(.evx-item-view) .header-actions{gap:12px}
body:not(.evx-item-view) .header-actions a{width:40px;height:40px;border:1px solid #e4e7eb;border-radius:10px;display:grid;place-items:center;font-size:14px;background:#fff}
body:not(.evx-item-view) .nav-wrap{background:#fff;border-top:1px solid #eef0f2;border-bottom:1px solid #e5e8eb}
body:not(.evx-item-view) .nav{height:44px;gap:32px;font-size:12px;font-weight:700}
body:not(.evx-item-view) .nav .deal{color:#ff7a00}
body:not(.evx-item-view) .shop-layout{max-width:1320px;margin:26px auto 48px;padding:0 20px;grid-template-columns:minmax(0,1fr) 235px;gap:24px}
body:not(.evx-item-view) .section-head{margin-bottom:16px}
body:not(.evx-item-view) .section-head h1{font-size:22px;line-height:1.2;margin-bottom:5px;font-weight:800;letter-spacing:-.5px}
body:not(.evx-item-view) .section-head p{font-size:12px;color:#77808b}
body:not(.evx-item-view) .grid-posts,
body:not(.evx-item-view) .feed-grid{gap:0;border-left:1px solid #e1e5e9;border-top:1px solid #e1e5e9;background:#fff}
body:not(.evx-item-view) .feed-card{border:0;border-right:1px solid #e1e5e9;border-bottom:1px solid #e1e5e9;border-radius:0;box-shadow:none;background:#fff}
body:not(.evx-item-view) .feed-card-image{background:#fff;aspect-ratio:1/1}
body:not(.evx-item-view) .feed-card-image img{object-fit:contain}
body:not(.evx-item-view) .feed-card-discount{left:10px;top:10px;background:#11151a;border-radius:5px;padding:6px 8px;font-size:10px}
body:not(.evx-item-view) .feed-card-body{padding:12px 14px 14px;gap:8px}
body:not(.evx-item-view) .feed-card-title{font-size:12px;line-height:1.42;font-weight:700;min-height:51px;color:#111820}
body:not(.evx-item-view) .feed-card-price-row{gap:8px;margin-top:0}
body:not(.evx-item-view) .feed-card-price{font-size:17px;color:#111820;font-weight:800}
body:not(.evx-item-view) .feed-card-old-price{font-size:10px;color:#a5abb3}
body:not(.evx-item-view) .feed-card-actions{gap:8px;margin-top:5px}
body:not(.evx-item-view) .feed-card-actions .view{height:36px;background:#11151a;color:#fff;border-radius:6px;font-size:12px;font-weight:800}
body:not(.evx-item-view) .feed-card-actions .details{height:36px;width:38px;border:1px solid #e2e5e9;border-radius:6px;background:#fff;color:#111820}
body:not(.evx-item-view) .sidebar .widget,
body:not(.evx-item-view) .trust-card{border:1px solid #e1e5e9;border-radius:10px;background:#fff;margin-bottom:16px;padding:15px}
body:not(.evx-item-view) .trust-card{background:#11151a;color:#fff;border-color:#11151a;box-shadow:0 8px 20px rgba(17,21,26,.12)}
body:not(.evx-item-view) .trust-card h3{color:#fff;font-size:14px}
body:not(.evx-item-view) .trust-card h3 i{color:#fff}
body:not(.evx-item-view) .trust-card p{color:#cbd1d8;font-size:11px;line-height:1.55}
body:not(.evx-item-view) .sidebar h3,
body:not(.evx-item-view) .widget-title h3{font-size:13px;font-weight:800}
body:not(.evx-item-view) .list-label a{font-size:11px;color:#59616d;padding:8px 0}
body:not(.evx-item-view) .footer{background:#11151a}
@media(max-width:980px){
 body:not(.evx-item-view) .shop-layout{grid-template-columns:1fr}
 body:not(.evx-item-view) .sidebar{display:none}
}
@media(max-width:680px){
 body:not(.evx-item-view) .site-shell{padding-left:12px;padding-right:12px}
 body:not(.evx-item-view) .shop-layout{padding:0 12px}
 body:not(.evx-item-view) .feed-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 body:not(.evx-item-view) .feed-card-title{font-size:11px;min-height:47px}
 body:not(.evx-item-view) .feed-card-price{font-size:15px}
}

/* ===== HOME CARD SIZE + MOTION ===== */
body:not(.evx-item-view) .shop-layout{max-width:1320px;padding:0 18px;grid-template-columns:minmax(0,1fr) 250px;gap:26px;}
body:not(.evx-item-view) .main-area{min-width:0}
body:not(.evx-item-view) .feed-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;border:0;background:transparent;}
body:not(.evx-item-view) .feed-card{position:relative;overflow:hidden;border:1px solid #e5e8ec;border-radius:11px;background:#fff;min-width:0;box-shadow:0 1px 2px rgba(16,24,40,.02);transform:translateY(0);transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease;}
body:not(.evx-item-view) .feed-card:hover{transform:translateY(-5px);border-color:#d9dee5;box-shadow:0 12px 28px rgba(16,24,40,.10);}
body:not(.evx-item-view) .feed-card-image{position:relative;display:block;aspect-ratio:1/1;overflow:hidden;background:#fff;}
body:not(.evx-item-view) .feed-card-image img{width:100%;height:100%;object-fit:contain;display:block;transform:scale(1);transition:transform .32s ease;}
body:not(.evx-item-view) .feed-card:hover .feed-card-image img{transform:scale(1.035)}
body:not(.evx-item-view) .feed-card-discount{left:10px;top:10px;background:#11151a;color:#fff;border-radius:5px;padding:6px 8px;font-size:10px;font-weight:800;z-index:4;}
body:not(.evx-item-view) .feed-card-heart{position:absolute;top:10px;right:10px;z-index:4;width:31px;height:31px;border:1px solid #e3e7eb;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.96);color:#98a1ab;font-size:13px;transition:background .2s ease,color .2s ease,transform .2s ease;}
body:not(.evx-item-view) .feed-card-heart:hover{background:#fff;color:#11151a;transform:scale(1.08);}
body:not(.evx-item-view) .feed-card-body{padding:11px 12px 10px;gap:7px;}
body:not(.evx-item-view) .feed-card-meta{min-height:16px;display:flex;align-items:center;justify-content:space-between;gap:8px;color:#7d8793;font-size:10px;line-height:1.2;}
body:not(.evx-item-view) .feed-card-meta .feed-store{color:#303844;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:50%;}
body:not(.evx-item-view) .feed-card-title{margin:0;color:#121820;font-size:12px;line-height:1.42;font-weight:700;min-height:51px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;}
body:not(.evx-item-view) .feed-card-rating{display:flex;align-items:center;gap:4px;min-height:15px;color:#8b939d;font-size:10px;}
body:not(.evx-item-view) .feed-card-rating .stars{color:#ff9f00;letter-spacing:.5px}
body:not(.evx-item-view) .feed-card-price-row{display:flex;align-items:baseline;gap:8px;min-height:23px;margin:1px 0 0;}
body:not(.evx-item-view) .feed-card-price{color:#11151a;font-size:18px;line-height:1.15;font-weight:800;}
body:not(.evx-item-view) .feed-card-old-price{color:#a5abb3;font-size:10px;text-decoration:line-through;}
body:not(.evx-item-view) .feed-card-actions{display:flex;gap:7px;padding:0 12px 12px;margin-top:auto;}
body:not(.evx-item-view) .feed-card-actions a{height:37px;transition:transform .18s ease,background .18s ease,border-color .18s ease;}
body:not(.evx-item-view) .feed-card-actions .view{flex:1;border-radius:6px;background:#11151a;color:#fff;font-size:12px;font-weight:800;}
body:not(.evx-item-view) .feed-card-actions .view:hover{background:#242a31;transform:translateY(-1px);}
body:not(.evx-item-view) .feed-card-actions .details{flex:0 0 39px;width:39px;border:1px solid #e0e4e8;border-radius:6px;background:#fff;color:#11151a;}
body:not(.evx-item-view) .feed-card-actions .details:hover{border-color:#bcc4cd;background:#f7f8f9;transform:translateY(-1px);}
body:not(.evx-item-view) .sidebar{width:auto}
body:not(.evx-item-view) .trust-card{padding:17px}
@media(max-width:1050px){body:not(.evx-item-view) .shop-layout{grid-template-columns:minmax(0,1fr) 225px;gap:20px}}
@media(max-width:980px){body:not(.evx-item-view) .shop-layout{grid-template-columns:1fr}body:not(.evx-item-view) .feed-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:560px){
  body:not(.evx-item-view) .feed-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
  body:not(.evx-item-view) .feed-card-body{padding:9px 9px 8px}
  body:not(.evx-item-view) .feed-card-actions{padding:0 9px 9px}
  body:not(.evx-item-view) .feed-card-meta .feed-store{display:none}
  body:not(.evx-item-view) .feed-card-title{font-size:11px;min-height:47px}
  body:not(.evx-item-view) .feed-card-price{font-size:16px}
}

/* ===== SEO / PROFESSIONAL TYPOGRAPHY ===== */
.sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
html{-webkit-text-size-adjust:100%}
body{font-family:Inter,"Noto Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;font-size:14px;line-height:1.55;font-weight:400;letter-spacing:-.01em;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;text-rendering:optimizeLegibility;font-kerning:normal;font-feature-settings:"kern" 1,"liga" 1,"calt" 1;}
button,input,select,textarea{font:inherit}
a,button,input{outline-offset:3px}
a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid #11151a;outline-offset:2px}
.brand,.nav,.section-head h1,.feed-card-title,.feed-card-price,.sidebar h3,.footer h3{letter-spacing:-.025em}
.section-head p,.product-meta,.feed-card-meta,.sidebar,.footer{letter-spacing:-.005em}

/* Search */
.header-main .searchbar{position:relative;height:46px;border:1px solid #d8dde3!important;border-radius:24px!important;background:#f8f9fa!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.85);transition:border-color .18s ease,box-shadow .18s ease,background .18s ease;}
.header-main .searchbar:focus-within{background:#fff!important;border-color:#aeb6c0!important;box-shadow:0 0 0 4px rgba(17,21,26,.07);}
.header-main .searchbar input{height:100%;padding:0 18px;background:transparent!important;color:#111827;font-size:13px;font-weight:450;}
.header-main .searchbar input::placeholder{color:#8a939f;opacity:1}
.header-main .searchbar button{width:58px;min-width:58px;height:100%;border:0;border-radius:0 23px 23px 0;background:#11151a!important;color:#fff!important;cursor:pointer;transition:background .18s ease,transform .18s ease;}
.header-main .searchbar button:hover{background:#272d34!important}
.header-main .searchbar button:active{transform:scale(.97)}
.mobile-search .searchbar{border:1px solid #d8dde3!important;border-radius:10px!important;background:#f8f9fa!important;}
.mobile-search .searchbar button{background:#11151a!important;color:#fff!important}

/* Sidebar widgets */
.sidebar-section .widget{border:1px solid #e3e7eb;border-radius:10px;background:#fff;margin:0 0 16px;padding:0;overflow:hidden;}
.sidebar-section .widget>h2,.sidebar-section .widget>h3,.sidebar-section .widget .title{margin:0;padding:14px 15px;border-bottom:1px solid #eceff2;color:#151a20;font-size:13px;line-height:1.25;font-weight:800;}
.sidebar-section .widget-content{padding:12px 15px}
.html-widget-content{color:#616b77;font-size:12px;line-height:1.65;}
.html-widget-content>*:first-child{margin-top:0}
.html-widget-content>*:last-child{margin-bottom:0}
.html-widget-content img{max-width:100%;height:auto;border-radius:7px}
.sidebar-section .list-label.widget-content{padding:5px 15px 9px}
.sidebar-section .list-label li{border-color:#eef1f3}
.sidebar-section .list-label a{padding:8px 0;font-size:11.5px;transition:color .15s ease,padding-left .15s ease}
.sidebar-section .list-label a:hover{color:#11151a;padding-left:3px}

/* Feed Pagination */
.evx-pagination{display:flex;align-items:center;justify-content:center;gap:7px;flex-wrap:wrap;margin:28px 0 4px;padding:0;}
.evx-pagination a,.evx-pagination span{min-width:38px;height:38px;padding:0 11px;border:1px solid #dfe4e9;border-radius:8px;background:#fff;color:#303844;display:inline-flex;align-items:center;justify-content:center;font-size:12px;line-height:1;font-weight:700;text-decoration:none;transition:background .18s ease,border-color .18s ease,color .18s ease,transform .18s ease;}
.evx-pagination a:hover{background:#f6f7f8;border-color:#bfc7d0;color:#11151a;transform:translateY(-1px);}
.evx-pagination .current{background:#11151a;border-color:#11151a;color:#fff;cursor:default;}
.evx-pagination .disabled{color:#b4bbc3;background:#f8f9fa;cursor:not-allowed;}
.evx-pagination .dots{border-color:transparent;background:transparent;min-width:28px;padding:0 4px;}
.evx-pagination .prev,.evx-pagination .next{padding:0 14px;min-width:auto;}
.evx-page-info{margin:11px 0 0;text-align:center;color:#8a939f;font-size:11px;}
@media(max-width:560px){
  .evx-pagination{gap:5px;margin-top:20px}
  .evx-pagination a,.evx-pagination span{min-width:34px;height:34px;padding:0 9px;font-size:11px;border-radius:7px;}
  .evx-pagination .prev,.evx-pagination .next{padding:0 10px}
  .evx-pagination .page-wide{display:none}
}

/* ===== MOBILE SINGLE PRODUCT RESPONSIVE FIX ===== */
@media (max-width:900px){
  body.evx-item-view{overflow-x:hidden;}
  body.evx-item-view .shop-layout{display:block!important;width:100%!important;max-width:100%!important;margin:16px auto 28px!important;padding:0 12px!important;}
  body.evx-item-view .main-area,body.evx-item-view #main-content,body.evx-item-view #evx-feed-app{width:100%!important;max-width:100%!important;min-width:0!important;margin:0!important;padding:0!important;overflow:visible!important;}
  body.evx-item-view .evx-product-page{width:100%!important;max-width:100%!important;margin:0!important;transform:none!important;padding:18px!important;border-radius:14px!important;overflow:hidden;}
  body.evx-item-view .evx-main{display:grid!important;grid-template-columns:1fr!important;gap:22px!important;width:100%!important;min-width:0!important;}
  body.evx-item-view .evx-gallery,body.evx-item-view .evx-summary{width:100%!important;min-width:0!important;}
  body.evx-item-view .evx-image-box{width:100%!important;max-width:100%!important;aspect-ratio:1/1!important;height:auto!important;padding:16px!important;}
  body.evx-item-view .evx-main-link,body.evx-item-view .evx-main-image,body.evx-item-view .evx-image-box img{width:100%!important;max-width:100%!important;height:100%!important;object-fit:contain!important;}
  body.evx-item-view .evx-thumbs{width:100%!important;max-width:100%!important;overflow-x:auto!important;overflow-y:hidden!important;-webkit-overflow-scrolling:touch;padding-bottom:6px!important;}
  body.evx-item-view .evx-title{font-size:23px!important;line-height:1.32!important;overflow-wrap:anywhere;word-break:normal;}
  body.evx-item-view .evx-breadcrumb{width:100%;max-width:100%;flex-wrap:nowrap!important;overflow-x:auto!important;overflow-y:hidden!important;white-space:nowrap;scrollbar-width:none;padding-bottom:3px;}
  body.evx-item-view .evx-breadcrumb::-webkit-scrollbar{display:none}
  body.evx-item-view .evx-breadcrumb .current{max-width:none!important;overflow:visible!important;text-overflow:clip!important;}
  body.evx-item-view .evx-price-box,body.evx-item-view .evx-buy-panel,body.evx-item-view .evx-specs{width:100%!important;max-width:100%!important;}
  body.evx-item-view .evx-price-line{align-items:baseline!important;}
  body.evx-item-view .evx-buy-actions{grid-template-columns:1fr 1.15fr!important;}
  body.evx-item-view .evx-benefits{grid-template-columns:repeat(3,minmax(0,1fr))!important;}
  body.evx-item-view .evx-benefit{min-width:0!important;}
  body.evx-item-view .evx-spec-row{grid-template-columns:120px minmax(0,1fr)!important;}
  body.evx-item-view .evx-spec-row > *{min-width:0;overflow-wrap:anywhere;}
  body.evx-item-view .evx-about,body.evx-item-view .evx-description{width:100%!important;max-width:100%!important;overflow-wrap:anywhere;}
  body.evx-item-view .evx-description img,body.evx-item-view .native-post-body img,body.evx-item-view .feed-item-body img{max-width:100%!important;height:auto!important;}
}
@media (max-width:600px){
  body.evx-item-view .top-strip{display:none!important;}
  body.evx-item-view .header-main .site-shell{height:58px!important;padding:0 12px!important;gap:10px!important;}
  body.evx-item-view .brand{font-size:21px!important;max-width:calc(100% - 54px);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  body.evx-item-view .header-main .searchbar{display:none!important;}
