  body:not(.evx-item-view) .evx-pagination span{min-width:34px!important;height:34px!important;padding:0 8px!important;font-size:11px!important}
  body:not(.evx-item-view) .evx-pagination .prev,
  body:not(.evx-item-view) .evx-pagination .next{font-size:0!important;min-width:34px!important}
  body:not(.evx-item-view) .evx-pagination .prev .fa,
  body:not(.evx-item-view) .evx-pagination .next .fa{font-size:13px!important}
}
/* ===== END HOME PAGINATION FINAL ===== */

body.script:
//
(function(){
  var nav=document.querySelector('.nav-wrap'),tog=document.querySelector('.menu-toggle'),back=document.querySelector('.back-top');
  if(tog&&nav)tog.onclick=function(){nav.classList.toggle('open')};
  window.addEventListener('scroll',function(){if(back)back.classList.toggle('show',window.pageYOffset>300)},{passive:true});
  if(back)back.onclick=function(){window.scrollTo({top:0,behavior:'smooth'})};

  document.querySelectorAll('.evx-search-form').forEach(function(form){
    form.addEventListener('submit',function(ev){
      var input=form.querySelector('input[name="q"]');
      var q=input?String(input.value||'').trim():'';
      if(!q)return;
      ev.preventDefault();
      location.href='/search?q='+encodeURIComponent(q);
    });
  });

  function esc(v){return String(v||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}

  function schemaText(root,selector){
    var el=root.querySelector(selector);
    return el ? String(el.textContent||'').replace(/\s+/g,' ').trim() : '';
  }
  function schemaNumber(v){
    var m=String(v||'').replace(/,/g,'').match(/-?\d+(?:\.\d+)?/);
    return m ? m[0] : '';
  }

  function injectProductSchema(root,title){
    if(!root)return;
    var d=root.dataset||{};
    var img=d.image||'';
    if(!img){
      var im=root.querySelector('.evx-main-image,.evx-image-box img');
      if(im)img=im.getAttribute('src')||'';
    }
    var desc=schemaText(root,'.evx-description');
    var price=schemaNumber(d.price||schemaText(root,'.evx-price'));
    var currency=(d.currency||'USD').toUpperCase();
    var canonical=document.querySelector('link[rel="canonical"]');
    var pageUrl=canonical&&canonical.href ? canonical.href : location.href;
    var buy=d.buy||'';
    var productId=String(d.productId||'').trim();
    var productUrl=productId ? 'https://www.aliexpress.com/item/'+encodeURIComponent(productId)+'.html' : pageUrl;
    var schema={
      '@context':'https://schema.org',
      '@type':'Product',
      '@id':productUrl+'#product',
      'name':title||schemaText(root,'.evx-title'),
      'url':productUrl,
      'sku':d.productId||'',
      'image':img?[img]:[],
      'description':desc,
      'offers':{
        '@type':'Offer',
        'url':productUrl,
        'priceCurrency':currency,
        'price':price,
        'availability':'https://schema.org/InStock'
      }
    };
    var rating=parseFloat(String(d.rating||'').replace(',','.'));
    var reviews=parseFloat(String(d.reviews||'').replace(/[^0-9.\-]/g,''));
    var sold=parseFloat(String(d.sold||'').replace(/[^0-9.\-]/g,''));

    if(isFinite(rating)&&rating>0&&isFinite(reviews)&&reviews>0){
      schema.aggregateRating={'@type':'AggregateRating','ratingValue':rating.toFixed(1),'bestRating':'5','worstRating':'1','reviewCount':String(Math.floor(reviews))};
    }
    if(isFinite(sold)&&sold>0){
      schema.interactionStatistic={'@type':'InteractionCounter','interactionType':{'@type':'BuyAction'},'userInteractionCount':Math.floor(sold)};
      schema.additionalProperty=schema.additionalProperty||[];
      schema.additionalProperty.push({'@type':'PropertyValue','name':'Sold','value':String(Math.floor(sold))});
    }
    if(!schema.sku)delete schema.sku;
    if(!schema.image.length)delete schema.image;
    if(!schema.description)delete schema.description;
    if(!schema.offers.price)delete schema.offers.price;
    var old=document.getElementById('evx-product-schema');
    if(old)old.remove();
    var script=document.createElement('script');
    script.id='evx-product-schema';
    script.type='application/ld+json';
    script.textContent=JSON.stringify(schema).replace(/<\//g,'<\\/');
    document.head.appendChild(script);
  }

  // SCRIPT RENDER POPULAR PRODUCTS DI SIDEBAR

  function lowestRupiah(v){
    var raw=String(v||'').trim();
    if(!raw)return '';
    var vals=[];
    var rp=/Rp\s*([\d.]+)/gi,m;
    while((m=rp.exec(raw))) vals.push(parseInt(m[1].replace(/\./g,''),10));
    if(!vals.length){
      var parts=raw.split(/\s*-\s*/);
      parts.forEach(function(x){
        var digits=String(x).replace(/[^0-9]/g,'');
        var n=parseInt(digits,10);
        if(isFinite(n)&&n>0) vals.push(n);
      });
    }
    if(!vals.length)return '';
    var n=Math.min.apply(Math,vals.filter(function(x){return isFinite(x)&&x>0;}));
    return isFinite(n) ? 'Rp'+n.toLocaleString('id-ID') : '';
  }

  var sidebarPopular = document.getElementById('evx-sidebar-popular');
  if(sidebarPopular){
    fetch('/feeds/posts/default?alt=json&max-results=5', {credentials:'same-origin'})
      .then(function(r){ return r.json(); })
      .then(function(json){
        var entries = json.feed && json.feed.entry || [];
        if(!entries.length){
          sidebarPopular.innerHTML = '<div style="padding:10px;color:#888;font-size:12px;">No products found.</div>';
          return;
        }
        var html = '<div class="popular-products-list">';
        entries.forEach(function(e){
          var title = e.title && e.title.$t || 'Untitled';
          var links = e.link || [];
          var url = '#';
          for(var i=0; i<links.length; i++){ if(links[i].rel === 'alternate'){ url = links[i].href; break; } }

          var content = e.content && e.content.$t || e.summary && e.summary.$t || '';
          var tmp = document.createElement('div');
          tmp.innerHTML = content;
          var box = tmp.querySelector('.evx-product');
          var d = box ? (box.dataset || {}) : {};
          var img = d.image || '';
          if(!img){ var im = tmp.querySelector('img'); if(im) img = im.getAttribute('src') || ''; }
          if(!img) img = 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%2272%22 height=%2272%22%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22%23fafbfc%22/%3E%3C/svg%3E';
          var price = String(d.price || '').trim();
          function sidebarRupiah(v){ return lowestRupiah(v); }
          price = sidebarRupiah(price);

          var rating=parseFloat(String(d.rating||'').replace(',','.'));
          var reviewRaw=String(d.reviews||d.reviewCount||d.ratingCount||'').trim();
          var reviews=parseInt(reviewRaw.replace(/[^0-9]/g,''),10);
          if(!(isFinite(rating)&&rating>0)){
            var rv=tmp.querySelector('[itemprop="ratingValue"]');
            if(rv)rating=parseFloat(String(rv.getAttribute('content')||rv.textContent||'').replace(',','.'));
          }
          if(!(reviews>0)){
            var rc=tmp.querySelector('[itemprop="reviewCount"],[itemprop="ratingCount"]');
            if(rc)reviews=parseInt(String(rc.getAttribute('content')||rc.textContent||'').replace(/[^0-9]/g,''),10);
          }
          var sidebarRating='';
          if((isFinite(rating)&&rating>0)||reviews>0){
            sidebarRating='<div class="popular-product-rating" style="display:flex;align-items:center;gap:4px;margin-top:4px;font-size:10px;line-height:1.2;color:#8d8580;white-space:nowrap;">'+
              (isFinite(rating)&&rating>0?'<span style="color:#b69a72;">★</span><strong style="color:#625b56;">'+esc(rating.toFixed(2).replace(/0$/,'').replace(/\.$/,''))+'</strong>':'')+
              (reviews>0?'<span>· '+esc(reviews.toLocaleString('id-ID'))+' ulasan</span>':'')+
            '</div>';
          }

          html += '<div class="popular-product-item" style="display:grid;grid-template-columns:62px minmax(0,1fr);gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid #eef1f3;">' +
                    '<a class="popular-product-thumb" href="'+esc(url)+'" style="width:62px;height:62px;display:block;overflow:hidden;border:1px solid #e7eaee;border-radius:8px;background:#fafbfc;">' +
                      '<img src="'+esc(img)+'" alt="'+esc(title)+'" style="width:100%;height:100%;object-fit:cover;display:block;" loading="lazy"/>' +
                    '</a>' +
                    '<div style="min-width:0;">' +
                      '<a class="popular-product-title" href="'+esc(url)+'" style="display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;color:#20262e;font-size:11.5px;line-height:1.4;font-weight:650;text-decoration:none;">'+esc(title)+'</a>' +
                      sidebarRating +
                      (price ? '<div class="popular-product-price" style="margin-top:4px;color:#8f5963;font-size:12px;font-weight:800;">'+esc(price)+'</div>' : '') +
                    '</div>' +
                  '</div>';
        });
        html += '</div>';
        sidebarPopular.innerHTML = html;
      })
      .catch(function(){
        sidebarPopular.innerHTML = '<div style="padding:10px;color:#888;font-size:12px;">Failed to load products.</div>';
      });
  }

  var isItemView = document.body.classList.contains('evx-item-view');
  if(isItemView) {
    var root = document.querySelector('.evx-product-page') || document.querySelector('.evx-product');
    if(root) {
      injectProductSchema(root, document.title.split(' - ')[0]);
      var mainImg=root.querySelector('.evx-main-image')||root.querySelector('.evx-image-box img');
      var mainLink=root.querySelector('.evx-main-link')||root.querySelector('.evx-image-box a');
      root.querySelectorAll('.evx-thumb').forEach(function(a){
        a.addEventListener('click',function(ev){
          ev.preventDefault();
          root.querySelectorAll('.evx-thumb').forEach(function(x){x.classList.remove('active')});
          a.classList.add('active');
          if(mainImg)mainImg.src=a.href;
          if(mainLink)mainLink.href=a.href;
        });
      });
    }
    return;
  }

  var app=document.getElementById('evx-feed-app');
  if(!app)return;

  function entryLink(e){
    var links=e.link||[];
    for(var i=0;i<links.length;i++)if(links[i].rel==='alternate')return links[i].href;
    return '#';
  }
  function htmlToDoc(html){var d=document.createElement('div'); d.innerHTML=html||''; return d;}
  function productData(html){
    var d=htmlToDoc(html), box=d.querySelector('.evx-product'), data=box?(box.dataset||{}):{};
    var img=data.image||'';
    if(!img){var im=d.querySelector('img');if(im)img=im.getAttribute('src')||''}
    return {doc:d,box:box,data:data,image:img};
  }
  function homeDiscountLabel(v){
    var s=String(v||'').trim();
    if(!s)return '';
    var m=s.match(/-?\d+(?:\.\d+)?/);
    if(!m)return '';
    var n=parseFloat(m[0]);
    if(!isFinite(n)||n<=0)return '';
    if(n>100)n=100;
    return (Math.round(n*10)/10).toString().replace(/\.0$/,'')+'% OFF';
  }

  function renderCard(e){
    var title=e.title&&e.title.$t||'Untitled';
    var url=entryLink(e);
    var content=e.content&&e.content.$t||e.summary&&e.summary.$t||'';
    var p=productData(content);
    var d=p.data||{};
    var price=String(d.price||'').trim();
    var oldPrice=String(d.oldPrice||'').trim();
    var discount=homeDiscountLabel(d.discount||'');
    var store=String(d.store||d.storeName||d.shop||'').trim();
    var buy=String(d.buy||'').trim();
    var rating=parseFloat(String(d.rating||'').replace(',','.'));
    var reviewRaw=String(d.reviews||d.reviewCount||d.ratingCount||'').trim();
    var reviews=parseInt(reviewRaw.replace(/[^0-9]/g,''),10);

    // Fallback: posting lama/baru bisa menyimpan rating & ulasan di HTML/schema,
    // bukan di data-* root. Ambil langsung dari isi posting agar card home tetap lengkap.
    if(!(isFinite(rating)&&rating>0)){
      var rv=p.doc.querySelector('[itemprop="ratingValue"]');
      if(rv) rating=parseFloat(String(rv.getAttribute('content')||rv.textContent||'').replace(',','.'));
    }
    if(!(reviews>0)){
      var rc=p.doc.querySelector('[itemprop="reviewCount"],[itemprop="ratingCount"]');
      if(rc) reviews=parseInt(String(rc.getAttribute('content')||rc.textContent||'').replace(/[^0-9]/g,''),10);
    }
    if(!(reviews>0)){
      var txt=(p.doc.body&&p.doc.body.textContent)||'';
      var rm=txt.match(/([\d.,]+\s*(?:RB|JT|K|M)?)\s*ulasan(?:\s*Shopee)?/i);
      if(!rm) rm=txt.match(/([\d.,]+\s*(?:RB|JT|K|M)?)\s*penilaian/i);
      if(rm){
        var x=rm[1].toUpperCase().replace(/\s+/g,'');
        var mult=1;
        if(/RB$/.test(x)){mult=1000;x=x.replace(/RB$/,'');}
        else if(/JT$/.test(x)){mult=1000000;x=x.replace(/JT$/,'');}
        else if(/K$/.test(x)){mult=1000;x=x.replace(/K$/,'');}
        else if(/M$/.test(x)){mult=1000000;x=x.replace(/M$/,'');}
        var num=Number(x.replace(/\./g,'').replace(',','.'));
        if(isFinite(num)) reviews=Math.round(num*mult);
      }
    }
    var image=p.image||'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22500%22 height=%22500%22%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22%23fafafa%22/%3E%3C/svg%3E';
    function rupiah(v){ return lowestRupiah(v); }
    price=rupiah(price);
    oldPrice=rupiah(oldPrice);

    var discountBadge=discount ? '<span class="feed-card-discount">'+esc(discount)+'</span>' : '';
    var storeHtml='<div class="feed-card-meta"><span class="aprinna-card-store"><i class="fa fa-shopping-bag"></i>&#160; Aprinna Store</span></div>';
    var ratingHtml='';
    if((isFinite(rating)&&rating>0)||reviews>0){
      var full=(isFinite(rating)&&rating>0)?Math.max(0,Math.min(5,Math.round(rating))):0;
      var stars=full?('★★★★★'.slice(0,full)+'☆☆☆☆☆'.slice(0,5-full)):'';
      ratingHtml='<div class="feed-card-rating">'+(stars?'<span class="stars">'+stars+'</span>':'')+(isFinite(rating)&&rating>0?'<strong>'+esc(rating.toFixed(2).replace(/0$/,'').replace(/\.$/,''))+'</strong>':'')+(reviews>0?'<span class="feed-card-reviews">· '+esc(reviews.toLocaleString('id-ID'))+' ulasan</span>':'')+'</div>';
    }

    var priceHtml='';
    if(price||oldPrice){
      priceHtml='<div class="feed-card-price-row">'+(price?'<span class="feed-card-price">'+esc(price)+'</span>':'')+(oldPrice&&oldPrice!==price?'<span class="feed-card-old-price">'+esc(oldPrice)+'</span>':'')+'</div>';
    }else{
      priceHtml='<div class="feed-card-price-row"><span class="feed-card-price">View product</span></div>';
    }

    var actionUrl=buy||url;
    var actionAttrs=buy?' target="_blank" rel="noopener follow"':'';

    return '<article class="feed-card"><a class="feed-card-image" href="'+esc(url)+'" rel="follow">'+discountBadge+'<span class="feed-card-heart"><i class="fa fa-heart-o"></i></span><img src="'+esc(image)+'" alt="'+esc(title)+'" loading="lazy" decoding="async" width="350" height="350"></a><div class="feed-card-body">'+storeHtml+'<h2 class="feed-card-title"><a href="'+esc(url)+'" rel="follow">'+esc(title)+'</a></h2>'+ratingHtml+priceHtml+'</div><div class="feed-card-actions"><a class="view" href="'+esc(url)+'" rel="follow"><i class="fa fa-info-circle"></i>&#160; Detail</a><a class="details aprinna-buy-now" href="'+esc(actionUrl)+'"'+actionAttrs+' aria-label="Buy Now" title="Buy Now"><i class="fa fa-shopping-bag"></i><span>Buy Now</span></a></div></article>';
  }

  function feedTotal(feed){var n=parseInt(feed&&feed.openSearch$totalResults&&feed.openSearch$totalResults.$t,10); return isFinite(n)&&n>0?n:0;}
  function pageHref(page){
    var u=new URL(location.href);
    if(page<=1)u.searchParams.delete('page'); else u.searchParams.set('page',String(page));
    return u.pathname+(u.searchParams.toString()?'?'+u.searchParams.toString():'')+(u.hash||'');
  }

  function renderPagination(current,totalPages,totalItems,pageSize){
    if(totalPages<=1)return '';
    var pages=[];
    function pushPage(n){if(n>=1&&n<=totalPages&&pages.indexOf(n)===-1)pages.push(n);}
    pushPage(1); pushPage(2);
    for(var n=current-2;n<=current+2;n++)pushPage(n);
    pushPage(totalPages-1); pushPage(totalPages);
    pages.sort(function(a,b){return a-b});

    var html='<nav class="evx-pagination" aria-label="Navigasi halaman produk">';
    html+= current>1 ? '<a class="prev" href="'+esc(pageHref(current-1))+'" rel="prev"><i class="fa fa-angle-left" aria-hidden="true"></i>&#160; Sebelumnya</a>' : '<span class="prev disabled"><i class="fa fa-angle-left" aria-hidden="true"></i>&#160; Sebelumnya</span>';

    var last=0;
    pages.forEach(function(n){
      if(last && n-last>1)html+='<span class="dots">…</span>';
      if(n===current) html+='<span class="current" aria-current="page">'+n+'</span>';
      else html+='<a class="'+((n!==1&&n!==totalPages&&Math.abs(n-current)>1)?' page-wide':'')+'" href="'+esc(pageHref(n))+'" aria-label="Halaman '+n+'">'+n+'</a>';
      last=n;
    });

    html+= current<totalPages ? '<a class="next" href="'+esc(pageHref(current+1))+'" rel="next">Berikutnya&#160; <i class="fa fa-angle-right" aria-hidden="true"></i></a>' : '<span class="next disabled">Berikutnya&#160; <i class="fa fa-angle-right" aria-hidden="true"></i></span>';
    html+='</nav><div class="evx-page-info">Menampilkan '+(((current-1)*pageSize)+1)+'–'+Math.min(current*pageSize,totalItems)+' dari '+totalItems+' produk</div>';
    return html;
  }

  function fail(err){app.innerHTML='<div class="evx-error"><strong>Posts could not be loaded.</strong><br>'+esc(err&&err.message||err)+'</div>';}

  var params=new URLSearchParams(location.search||'');
  var searchQuery=String(params.get('q')||'').trim();

  // Blogger label route: /search/label/Nama%20Label
  var labelName='';
  var labelMatch=location.pathname.match(/^\/search\/label\/([^/?#]+)/i);
  if(labelMatch){
    try{ labelName=decodeURIComponent(labelMatch[1].replace(/\+/g,' ')); }
    catch(_e){ labelName=labelMatch[1]; }
  }

  var currentPage=parseInt(params.get('page')||'1',10);
  if(!isFinite(currentPage)||currentPage<1)currentPage=1;
  var pageSize=12;

  if(searchQuery){
    document.querySelectorAll('.evx-search-form input[name="q"]').forEach(function(input){input.value=searchQuery;});
  }

  var startIndex=((currentPage-1)*pageSize)+1;
  var endpoint='/feeds/posts/default';
  if(labelName) endpoint+='/-/'+encodeURIComponent(labelName);
  endpoint+='?alt=json&max-results='+pageSize+'&start-index='+startIndex;
  if(searchQuery) endpoint+='&q='+encodeURIComponent(searchQuery);

  fetch(endpoint,{credentials:'same-origin'})
    .then(function(r){if(!r.ok)throw new Error('Feed HTTP '+r.status);return r.json()})
    .then(function(json){
      var entries=json.feed&&json.feed.entry||[];
      if(!entries.length){
        if(searchQuery) app.innerHTML='<div class="evx-search-state"><h1>Search Results</h1><p>No products found for &quot;'+esc(searchQuery)+'&quot;.</p></div>';
        else app.innerHTML='<div class="evx-error">No published posts found.</div>';
        return;
      }
      var heading=searchQuery
        ? '<div class="evx-search-state"><h1>Hasil Pencarian</h1><p>Hasil untuk &quot;'+esc(searchQuery)+'&quot;</p></div>'
        : labelName
          ? '<div class="section-head"><div><h1>'+esc(labelName)+'</h1><p>Produk dalam label '+esc(labelName)+'.</p></div></div>'
          : '<div class="section-head"><div><h1>PRODUK KAMI</h1><p>Temukan produk populer dan penawaran terbaru untuk Anda.</p></div></div>';
      var totalItems=feedTotal(json.feed);
      var totalPages=totalItems?Math.ceil(totalItems/pageSize):1;
      if(totalPages>0 && currentPage>totalPages){ location.replace(pageHref(totalPages)); return; }
      var pager=renderPagination(currentPage,totalPages,totalItems,pageSize);
      app.innerHTML=heading+'<div class="feed-grid">'+entries.map(renderCard).join('')+'</div>'+pager;
    }).catch(fail);
})();
//
